/* Sound categories (Discussion #90): every sound in the PRESETS list belongs to one, so KNOB 4 (LIST) can show
 * only the basses, the leads, .. (ui.c list_mode). Factory presets: <M>_CAT[k] of each machine's 32 (four_presets.h,
 * generated by tools/four_presets.py from presets/four/<m>.py, which also enforces the counts and that ACID's
 * category is ACID's only); user presets: a byte of their record (upreset.c up_cat, set on the NAME screen when
 * saving or renaming, ui_name.c). Included by engines.c (the presets) and upreset.c (the host build of the user
 * presets needs the numbers only).
 * The numbers are stored (a user preset's record, the editor's UP_LIST / UP_GET / UP_PUT, the settings' LIST filter):
 * the VOID FOUR format's, append-only from here. CAT_NONE is a record without one: its category follows from its
 * engine (cat_of_engine) */
enum { CAT_NONE, CAT_BASS, CAT_LEAD, CAT_KEYS, CAT_BRASS, CAT_STRINGS, CAT_ATMOS, CAT_ACID, NCAT };
static const char *const CAT_NAME[NCAT] = {"-", "BASS", "LEAD", "KEYS", "BRASS", "STRINGS", "ATMOS", "ACID"};
/* the category a sound without one is listed under: its machine's main one (OB-Z LEAD, WAVE ATMOS, ACID, DRIFT BASS) */
static uint32_t cat_of_engine(uint32_t e) { return e == 1u ? CAT_ATMOS : e == 2u ? CAT_ACID : e == 3u ? CAT_BASS : CAT_LEAD; }
