        int32_t x = mulq15(rev_in[i], 2580), r = ln[(wp - (uint32_t)L) & (4096u - 1u)], p, o;
        int32_t t0 = ln[(wp - (uint32_t)L2) & (4096u - 1u)], t1 = ln[(wp - (uint32_t)L2 - 1u) & (4096u - 1u)];
        PKV(27).sp_lp += mulq15(r - PKV(27).sp_lp, kl);
