        o = x - PKV(27).sp_hp + PKV(27).sp_he; /* the low cut, its step's remainder kept (as */
        PKV(27).sp_he = o & 63; /* dc_block): no dead band to hold an offset in the loop */
        PKV(27).sp_hp += o >> 6;
