            int32_t v = (x - ap[j + k]) * 2867; /* towards 0, as the loop's gain: floors would feed */
            o = ap[j + k]; /* the loop a little offset and noise for ever */
            x = ((v + ((v >> 31) & 4095)) >> 12) + p;
            p = o;
