        PKV(28).y[2][i] = (int16_t)clamp(2 * p1 + y2 - y0 + x, -32768, 32767);
        PKV(28).y[3][i] = (int16_t)clamp(2 * p2 + y3 - y0 + x, -32768, 32767);
        PKV(28).y[4][i] = (int16_t)clamp(2 * p3 + y4 - y0 + x, -32768, 32767);
        PKV(28).y[5][i] = (int16_t)clamp(2 * p4 + y5 - y0 + x, -32768, 32767);
        PKV(28).y[6][i] = (int16_t)clamp(2 * p5 + y6 - y0 + x, -32768, 32767);
        PKV(28).y[7][i] = (int16_t)clamp(2 * p6 + y7 - y0 - x, -32768, 32767);
