    (*(volatile uint32_t *)0x12100u) = 0x40u | 0x80u | 0x1000u | 0x400u; /* RXDMA, RDC, clear R/OT; no IEs */
    __asm__ volatile("csync" ::: "memory");
    (*(volatile uint32_t *)0x12100u) |= 1u; /* UTEN last */
