static int chain_owns(uint32_t id) { return (id >= P_SLEN && id <= P_SGATE) || id == P_SQNT; }
static const step_t *seq_steps(const track_t *t)
{
    uint32_t k = (uint32_t)(t - PKV(2)), s;
    if (!PKV(103).running)
        return t->step;
    s = PKV(103).lane[k];
    return s < 4u ? PKV(103).source[s].step[k] : chain_silent;
}
static void motion_restore(track_t *t);
/* a section starts (chain_start, chain_tick: once a section, not per block; not inlined: off the audio ISR's loop) */
static void chain_apply(void)
{
    uint32_t i;
    const chain_row_t *r = &PKV(103).config.row[PKV(103).row];
    PKV(103).clk = (uint8_t)chain_clock(r);
    for (i = 0; i < 4; i++) {
        track_t *t = &PKV(2)[i];
        uint32_t s = r->slot[i];
        PKV(103).lane[i] = (uint8_t)(s < 4u ? s : 4u);
        seq_release(t);
        motion_restore(t);
        if (s < 4u) {
            memcpy(&t->p[P_SLEN], PKV(103).source[s].timing[i], sizeof PKV(103).timing[i]);
            t->p[P_SQNT] = PKV(103).source[s].qnt[i];
        } else {
            t->p[P_SLEN] = 16;
            t->p[P_SDIV] = 2;
            t->p[P_SSWING] = 0;
            t->p[P_SQNT] = 1;
        }
        t->seq_idx = (uint16_t)(t->p[P_SLEN] - 1);
        t->seq_pos = 0x7FFFFFFFu;
        t->rh_n = t->rskip_n = 0;
    }
}
static void chain_start(void)
{
    uint32_t i;
    if (!PKV(103).armed)
        return;
    PKV(103).rec = PKV(3).rec;
    PKV(3).rec = 0;
    for (i = 0; i < 4; i++) {
        memcpy(PKV(103).timing[i], &PKV(2)[i].p[P_SLEN], sizeof PKV(103).timing[i]);
        PKV(103).qnt[i] = (uint8_t)PKV(2)[i].p[P_SQNT];
    }
    PKV(103).row = 0;
    PKV(103).remaining = PKV(103).config.row[0].repeat;
    PKV(103).carry = 0;
    PKV(103).running = 1;
    PKV(103).armed = 0;
    chain_apply();
}
static void chain_stop(void)
{
    uint32_t i;
    PKV(103).armed = 0;
    if (!PKV(103).running)
        return;
    for (i = 0; i < 4; i++) {
        memcpy(&PKV(2)[i].p[P_SLEN], PKV(103).timing[i], sizeof PKV(103).timing[i]);
        PKV(2)[i].p[P_SQNT] = PKV(103).qnt[i];
    }
    PKV(3).rec = PKV(103).rec;
    PKV(103).running = 0;
}
static void chain_tick(uint32_t n)
{
    const track_t *t = &PKV(2)[PKV(103).clk % 4];
    uint32_t length;
    if (!PKV(103).running || t->seq_pos >= 0x7FFFFFFFu || t->seq_idx + 1u != (uint32_t)t->p[P_SLEN])
        return;
    length = step_samples(t, div_samples((uint32_t)t->p[P_SDIV]), t->seq_idx);
    if (t->seq_pos + n < length)
        return;
    if (PKV(103).remaining > 1u) {
        PKV(103).remaining--;
        return;
    }
    if (PKV(103).row + 1u >= PKV(103).config.count) {
        seq_stop();
        return;
    }
    PKV(103).carry = t->seq_pos + n - length;
    PKV(103).row++;
    PKV(103).remaining = PKV(103).config.row[PKV(103).row].repeat;
    chain_apply();
}
